#include <iostream>

int main()
{
    int photos{};
    double sizeMb{};
    std::cin >> photos >> sizeMb;

    double totalMb{ photos * sizeMb };
    double totalGb{ totalMb / 1024 };

    std::cout << "Total: " << totalMb << " MB\n";
    std::cout << "That is " << totalGb << " GB\n";
    std::cout << "Left on a 64 GB card: " << 64 - totalGb << " GB\n";
    return 0;
}
